package com.cenedu.backend.ai.problem.render; import com.cenedu.backend.domain.problem.authoring.diagram.*; public final class CoordinateGraphSvgRenderer { public String render(CoordinateGraphDiagramSpecV1 s){int p=s.viewport().padding(),cx=s.viewport().width()/2,cy=s.viewport().height()/2;var b=new StringBuilder();b.append("<line x1=\"").append(p).append("\" y1=\"").append(cy).append("\" x2=\"").append(s.viewport().width()-p).append("\" y2=\"").append(cy).append("\" stroke=\"#000000\"/>");b.append("<line x1=\"").append(cx).append("\" y1=\"").append(p).append("\" x2=\"").append(cx).append("\" y2=\"").append(s.viewport().height()-p).append("\" stroke=\"#000000\"/>");for(var line:s.lines())b.append("<line x1=\"").append(cx-30).append("\" y1=\"").append(cy+30).append("\" x2=\"").append(cx+30).append("\" y2=\"").append(cy-30).append("\" stroke=\"#000000\"/>");return b.toString();} }
